            return not_found("customer")
        return Response(200, {"customer_id": value.customer_id, "order_count": value.order_count,
                              "lifetime_value_cents": value.lifetime_value_cents})

def order(api, customer_id="c1", *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_history_is_newest_first_and_only_for_that_customer(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    other = order(shop, "c2", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert [o["order_id"] for o in body["orders"]] == [second, first]
    assert other not in [o["order_id"] for o in body["orders"]]


def test_entries_have_exact_shape(shop):
    oid = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    entries = shop.insights.handle_order_history("c1").body["orders"]
    assert entries == [{"order_id": oid, "status": "placed", "total_cents": 2500}]


def test_total_matches_order_summary_including_discount(shop):
    standard = order(shop, "c1", ("LAMP", 2)).body["order_id"]
    gold = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    entries = {c: shop.insights.handle_order_history(c).body["orders"][0] for c in ("c1", "c2")}
    assert entries["c1"]["order_id"] == standard
    assert entries["c1"]["total_cents"] == shop.orders.handle_get(standard).body["total_cents"] == 10800
    assert entries["c2"]["order_id"] == gold
    assert entries["c2"]["total_cents"] == shop.orders.handle_get(gold).body["total_cents"] == 10200


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders(shop):
    order(shop, "c1", ("BOOK", 1))                       # 2500, no discount
    lamp = order(shop, "c1", ("LAMP", 2)).body["order_id"]  # 12000 less 10% = 10800
    cancelled = order(shop, "c1", ("PEN", 2)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    order(shop, "c2", ("PEN", 1))                        # other customer, ignored
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 13300}
    history = shop.insights.handle_order_history("c1").body["orders"]
    live_totals = [o["total_cents"] for o in history if o["status"] != "cancelled"]
    assert response.body["lifetime_value_cents"] == sum(live_totals)
    assert lamp in [o["order_id"] for o in history]


def test_lifetime_value_applies_gold_discount(shop):
    order(shop, "c2", ("LAMP", 2))                       # 12000 less 15% = 10200
    response = shop.insights.handle_lifetime_value("c2")
    assert response.body == {"customer_id": "c2", "order_count": 1, "lifetime_value_cents": 10200}


def test_cancelled_orders_are_included_with_status(shop):
    oid = order(shop, "c1", ("LAMP", 2)).body["order_id"]
    shop.orders.handle_cancel(oid)
    entries = shop.insights.handle_order_history("c1").body["orders"]
    assert entries == [{"order_id": oid, "status": "cancelled", "total_cents": 10800}]

